    def make_panel_rect(self):
        return Rectangle(
            width=3.5,
            height=3.8,
            stroke_color=GREY_B,
            stroke_width=2,
            fill_color=WHITE,
            fill_opacity=0.05,
        )

    def build_neuron(self, color=TEAL):
        soma = Circle(
            radius=0.17,
            fill_color=color,
            fill_opacity=0.28,
            stroke_color=color,
            stroke_width=2,
        ).move_to(ORIGIN)

        dendrites = VGroup()
        for theta_deg in [150, 180, 210, 130, 230]:
            theta = np.deg2rad(theta_deg)
            start = soma.get_center() + 0.19 * np.array([np.cos(theta), np.sin(theta), 0])
            end = soma.get_center() + 0.58 * np.array([np.cos(theta), np.sin(theta), 0])
            dendrites.add(Line(start, end, color=color, stroke_width=2))

        axon = Line(
            soma.get_right(),
            soma.get_right() + RIGHT * 2.0,
            color=color,
            stroke_width=2,
        )
        terminals = VGroup(
            Line(axon.get_end(), axon.get_end() + RIGHT * 0.15 + UP * 0.13, color=color, stroke_width=1.5),
            Line(axon.get_end(), axon.get_end() + RIGHT * 0.15 + DOWN * 0.13, color=color, stroke_width=1.5),
            Line(axon.get_end(), axon.get_end() + RIGHT * 0.15, color=color, stroke_width=1.5),
        )
        return VGroup(soma, dendrites, axon, terminals)

    def build_waveform(self, color=TEAL):
        xs = np.array([-1.3, -1.1, -0.9, -0.7, -0.5, -0.3, 0.0, 0.5, 1.3])
        ys = np.array([0.0, 0.05, 0.75, 0.48, -0.55, -0.15, 0.0, 0.0, 0.0])
        points = [ORIGIN + RIGHT * x + UP * y for x, y in zip(xs, ys)]
        segments = VGroup()
        for i in range(len(points) - 1):
            segments.add(Line(points[i], points[i + 1], color=color, stroke_width=2.5))
        return segments, xs, ys

    def build_eeg_cap(self, color=TEAL):
        head = Ellipse(
            width=1.1,
            height=1.2,
            stroke_color=GREY_B,
            stroke_width=2,
            fill_color=GREY_B,
            fill_opacity=0.08,
        )
        dots = VGroup()
        for i in range(7):
            t = -0.8 + i * (1.6 / 6.0)
            x = 0.42 * t
            y = 0.52 * np.sqrt(max(0.0, 1.0 - (x / 0.5) ** 2))
            dot = Dot(point=np.array([x, y, 0]), radius=0.03, color=color, fill_opacity=1)
            dots.add(dot)
        return VGroup(head, dots), dots

    def build_synapse(self, color=ORANGE):
        presyn = Circle(
            radius=0.30,
            fill_color=color,
            fill_opacity=0.30,
            stroke_color=color,
            stroke_width=2,
        ).move_to(LEFT * 0.85 + UP * 0.08)

        membrane = Rectangle(
            width=0.08,
            height=1.2,
            fill_color=color,
            fill_opacity=0.45,
            stroke_color=color,
            stroke_width=1.5,
        ).move_to(RIGHT * 0.15)

        receptors = VGroup(*[
            Circle(
                radius=0.05,
                fill_color=color,
                fill_opacity=1,
                stroke_width=0,
            ).move_to(RIGHT * 0.20 + UP * y)
            for y in [0.35, 0.08, -0.18]
        ])

        dendrite = Line(
            membrane.get_right(),
            membrane.get_right() + RIGHT * 1.0,
            color=color,
            stroke_width=2,
        )

        group = VGroup(presyn, membrane, receptors, dendrite)
        group.scale_to_fit_width(2.6)
        return group, presyn, receptors

    def build_network(self, color=GREEN):
        left_nodes = VGroup(*[
            Circle(radius=0.07, fill_color=color, fill_opacity=0.75, stroke_width=0).move_to(LEFT * 1.25 + UP * y)
            for y in [0.60, 0.0, -0.60]
        ])
        central_nodes = VGroup(*[
            Circle(radius=0.07, fill_color=color, fill_opacity=0.75, stroke_width=0).move_to(RIGHT * 0.05 + UP * y)
            for y in [0.70, 0.24, -0.24, -0.70]
        ])
        right_nodes = VGroup(*[
            Circle(radius=0.07, fill_color=color, fill_opacity=0.75, stroke_width=0).move_to(RIGHT * 1.45 + UP * y)
            for y in [0.35, -0.35]
        ])

        arrows = VGroup(
            Arrow(left_nodes[0].get_right(), central_nodes[0].get_left(), color=color, buff=0.03, stroke_width=1.3),
            Arrow(left_nodes[1].get_right(), central_nodes[1].get_left(), color=color, buff=0.03, stroke_width=1.3),
            Arrow(left_nodes[2].get_right(), central_nodes[2].get_left(), color=color, buff=0.03, stroke_width=1.3),
            Arrow(central_nodes[0].get_right(), central_nodes[1].get_left(), color=color, buff=0.03, stroke_width=1.3),
            Arrow(central_nodes[1].get_right(), central_nodes[3].get_left(), color=color, buff=0.03, stroke_width=1.3),
            Arrow(central_nodes[3].get_right(), central_nodes[2].get_left(), color=color, buff=0.03, stroke_width=1.3),
            Arrow(central_nodes[2].get_right(), central_nodes[0].get_left(), color=color, buff=0.03, stroke_width=1.3),
            Arrow(central_nodes[0].get_right(), right_nodes[0].get_left(), color=color, buff=0.03, stroke_width=1.3),
            Arrow(central_nodes[2].get_right(), right_nodes[1].get_left(), color=color, buff=0.03, stroke_width=1.3),
        )

        label_left = Text("sensory", font_size=15, color=WHITE).rotate(PI / 2).next_to(left_nodes, LEFT, buff=0.08)
        label_center = Text("neural circuits", font_size=15, color=WHITE).next_to(central_nodes, UP, buff=0.06)
        label_right = Text("motor", font_size=15, color=WHITE).rotate(-PI / 2).next_to(right_nodes, RIGHT, buff=0.08)

        group = VGroup(arrows, left_nodes, central_nodes, right_nodes, label_left, label_center, label_right)
        group.scale_to_fit_width(3.0)
        return group, left_nodes, central_nodes, right_nodes

    def make_charge_updater(self, left_bound, right_bound, speed):
        def updater(mob, dt):
            mob.phase += dt * speed
            if mob.phase > 1.0:
                mob.phase -= 1.0
            x = left_bound + mob.phase * (right_bound - left_bound)
            mob.move_to(np.array([x, mob.base_y, 0]))
        return updater

    def make_mol_updater(self):
        def updater(mob, dt):
            mob.phase += dt * 0.45
            if mob.phase > 1.0:
                mob.phase -= 1.0
            ph = mob.phase

            if ph < 0.55:
                t = ph / 0.55
                mob.move_to(mob.start_pos + (mob.mid_pos - mob.start_pos) * t)
                mob.set_opacity(1)
                mob.flash.set_opacity(0)
            elif ph < 0.72:
                mob.move_to(mob.end_pos)
                mob.set_opacity(1)
                mob.flash.set_opacity(1)
            elif ph < 0.82:
                mob.move_to(mob.end_pos)
                mob.set_opacity(0)
                mob.flash.set_opacity(0)
            else:
                mob.move_to(mob.start_pos)
                mob.set_opacity(1)
                mob.flash.set_opacity(0)
        return updater

    def make_route_updater(self, speed):
        def updater(mob, dt):
            mob.progress += dt * speed
            if mob.progress >= len(mob.route) - 1:
                mob.progress = 0.0
            i = int(mob.progress)
            frac = mob.progress - i
            pos = mob.route[i] * (1 - frac) + mob.route[min(i + 1, len(mob.route) - 1)] * frac
            mob.move_to(pos)
        return updater

    def make_glow_updater(self):
        def updater(mob, dt):
            mob.phase += dt
            mob.set_opacity(0.07 + 0.06 * np.sin(mob.phase * 3.0))
        return updater

    def make_linear_updater(self, speed):
        def updater(mob, dt):
            mob.phase += dt * speed
            if mob.phase > 1.0:
                mob.phase -= 1.0
            mob.move_to(mob.start + (mob.end - mob.start) * mob.phase)
        return updater

