    def make_computing_icon(self, color=GREEN):
        points = [
            LEFT * 0.50 + UP * 0.32,
            LEFT * 0.25 + DOWN * 0.18,
            RIGHT * 0.02 + UP * 0.10,
            RIGHT * 0.45 + DOWN * 0.28,
        ]
        nodes = VGroup(*[
            Dot(point=pt, radius=0.045, color=color) for pt in points
        ])
        edges = VGroup(
            Line(points[0], points[1], color=color, stroke_width=1.5),
            Line(points[0], points[2], color=color, stroke_width=1.5),
            Line(points[1], points[3], color=color, stroke_width=1.5),
            Line(points[2], points[3], color=color, stroke_width=1.5),
            Arrow(points[1] + LEFT * 0.05, points[2], color=color, buff=0.03, stroke_width=1.3),
        )
        label_a = Text("A", font_size=12, color=WHITE).next_to(points[2], UP, buff=0.05)
        label_b = Text("B", font_size=12, color=WHITE).next_to(points[3], DOWN, buff=0.05)
        return VGroup(nodes, edges, label_a, label_b)